add_shortcode( 'out_of_stock_products', 'perfectpixel_out_of_stock_products_shortcode' );
add_filter( 'woocommerce_shortcode_products_query', 'perfectpixel_out_of_stock_products_query', 10, 3 );

function perfectpixel_out_of_stock_products_shortcode( $atts ) {
	if ( ! class_exists( 'WC_Shortcode_Products' ) ) {
		return '';
	}
	$atts          = (array) $atts;
	$atts['class'] = trim( ( $atts['class'] ?? '' ) . ' perfectpixel-out-of-stock' );
	$shortcode     = new WC_Shortcode_Products( $atts, 'products' );
	return $shortcode->get_content();
}

function perfectpixel_out_of_stock_products_query( $args, $atts, $type ) {
	if ( false !== strpos( (string) ( $atts['class'] ?? '' ), 'perfectpixel-out-of-stock' ) ) {
		$args['tax_query'][] = array(
			'taxonomy' => 'product_visibility',
			'field'    => 'name',
			'terms'    => array( 'outofstock' ),
			'operator' => 'IN',
		);
	}
	return $args;
}
